def transform(grid):
    out=[row[:] for row in grid]
    for r,row in enumerate(grid):
        best=max(range(1,10), key=lambda s:sum(v!=0 and v==((s-1+c)%9)+1 for c,v in enumerate(row)))
        for c,v in enumerate(row):
            if v==0: out[r][c]=((best-1+c)%9)+1
    return out
